      "link_oficial": "https://agenciabrasil.ebc.com.br/saude/noticia/2026-10/saude-aprova-protocolo-para-tratar-criancas-com-hemofilia",
      "categoria": "Últimas Notícias",
      "fonte": "Agência Brasil / EBC (Empresa Brasil de Comunicação)",
